// LabBook 1.0.1 — confirmation of DEF-12 and regression around the cancellation, executed.
const TEST_CASES = [
  {
    id: 'CF-01',
    kind: 'CONFIRMATION',
    description: 'DEF-12: a booking that starts in less than 2 hours can no longer be cancelled',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 9, duration: 1 },
        expect: { status: 201, body: { code: 'BK0001', status: 'CONFIRMED' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 409, body: { error: 'TOO_LATE' } } },
    ],
  },
  {
    id: 'CF-02',
    kind: 'CONFIRMATION',
    description: 'DEF-12 boundary: exactly 2 hours before the start the cancellation is still allowed',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-02', startHour: 10, duration: 1 },
        expect: { status: 201 },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
    ],
  },
  {
    id: 'RG-01',
    kind: 'REGRESSION',
    description: 'cancelling a future booking is stored in the database, not only answered',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 2 },
        expect: { status: 201 },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student1',
        call: 'GET /test/db/bookings',
        expect: { status: 200, body: [{ code: 'BK0001', status: 'CANCELLED' }] },
      },
    ],
  },
  {
    id: 'RG-02',
    kind: 'REGRESSION',
    description: 'promotion after a cancellation: first come, first served, and the promoted student is e-mailed',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      {
        as: 'student3',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200 } },
      {
        as: 'student2',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: [{ code: 'BK0002', status: 'CONFIRMED' }] },
      },
      {
        as: 'student3',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: [{ code: 'BK0003', status: 'PENDING' }] },
      },
      {
        as: 'admin',
        call: 'GET /test/outbox',
        expect: { status: 200, body: [{  }, {  }, {  }, { to: 'binh@fpt.edu.vn', subject: 'Booking confirmed', ref: 'BK0002' }] },
      },
    ],
  },
  {
    id: 'RG-03',
    kind: 'REGRESSION',
    description: 'only the owner can cancel',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      { as: 'student2', call: 'DELETE /api/bookings/BK0001', expect: { status: 403, body: { error: 'NOT_OWNER' } } },
    ],
  },
  {
    id: 'RG-04',
    kind: 'REGRESSION',
    description: 'a cancelled booking cannot be cancelled again; an unknown code is not found',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0001', expect: { status: 200 } },
      {
        as: 'student1',
        call: 'DELETE /api/bookings/BK0001',
        expect: { status: 409, body: { error: 'ALREADY_CANCELLED' } },
      },
      {
        as: 'student1',
        call: 'DELETE /api/bookings/BK9999',
        expect: { status: 404, body: { error: 'BOOKING_NOT_FOUND' } },
      },
    ],
  },
  {
    id: 'RG-05',
    kind: 'REGRESSION',
    description: 'cancelled hours no longer count toward the weekly 6-hour limit',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-04', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-05', startHour: 9, duration: 3 },
        expect: { status: 201 },
      },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-06', startHour: 9, duration: 1 },
        expect: { status: 422, body: { error: 'WEEKLY_LIMIT' } },
      },
      { as: 'student1', call: 'DELETE /api/bookings/BK0002', expect: { status: 200 } },
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB01', date: '2026-11-06', startHour: 9, duration: 1 },
        expect: { status: 201 },
      },
    ],
  },
  {
    id: 'RG-06',
    kind: 'REGRESSION',
    description: 'cancelling a PENDING booking does not promote anybody',
    precondition: 'Seed data; clock Mon 2026-11-02 08:00; build 1.0.1',
    steps: [
      {
        as: 'student1',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'CONFIRMED' } },
      },
      {
        as: 'student2',
        call: 'POST /api/bookings',
        body: { labCode: 'LAB02', date: '2026-11-04', startHour: 9, duration: 1 },
        expect: { status: 201, body: { status: 'PENDING' } },
      },
      { as: 'student2', call: 'DELETE /api/bookings/BK0002', expect: { status: 200, body: { status: 'CANCELLED' } } },
      {
        as: 'student1',
        call: 'GET /api/bookings/me',
        expect: { status: 200, body: [{ code: 'BK0001', status: 'CONFIRMED' }] },
      },
    ],
  },
];

const STRATEGY = {
  trigger: 'Modification',
  level: 'System testing',
  type: 'Change-related testing',
  automateFirst: 'REGRESSION',
  depthDecidedBy: 'Impact analysis and risk',
};

